const $ = sel => document.querySelector(sel);
const $$ = sel => [...document.querySelectorAll(sel)];
const sleep = ms => new Promise(r=>setTimeout(r,ms));
const clamp...

const state = {...};

// ---------- Setup ----------
function newSide(owner) {
  return {owner, lp:8000, deck:shuffle(DECK_LIST.slice()), extra:EXTRA_LIST.slice(), hand:[], monsters:[null...], spells:[null...], field:null, graveyard:[], hasSummoned:false};
}

function shuffle(a) { for ... }

function init() {
  buildBoard();
