```

State reset on start:
```js
function startGame() {
  closeModal();
  state.players = {player:newSide('player'), opponent:newSide('opponent')};
  state.emz=[null,null]; state.turn=1; state.active='player'; state.over=false; state.busy=false;
  state.mode='idle'; state.pending=null; state.selection=null;
  state.log=[]; state.running=true;
  state.timerStart=performance.now(); state.elapsed=0;
  startTimerLoop();
  dealOpening(); // 5 each
  addLog('system','決闘開始！ 最速でLPを0にしろ');
  startPlayerTurn(true);
  render();
}
```
startPlayerTurn(draw=true):
```js
state.active='player';
state.turn (already)
resetTurn(state.players.player);
addLog(...);
drawCards(player,1);
state.busy=false;
render();
```
For first turn: turn=1.

`resetTurn(side)`: side.hasSummoned=false; for all own monsters: changed=false, attacked=false. Clear temporary boosts at end of owner's turn, not start? Boost lasts "this turn". Clear at start of turn safe. Actually endTurn clears boosts for the side ending. Simpler: reset at start of each turn for that side (boosts from previous turn gone). Good.

`endPlayerTurn()`:
```js
if (state.busy || state.over || state.active!=='player') return;
cancelModes();
clearBoosts(player);
state.active='opponent';
state.busy=true; // AI controls
render();
setTimeout(()=>aiTurn(), 500);
```
Keep busy true during AI.

AI turn async:
```js
async function aiTurn() {
  const ai=state.players.opponent;
  if (state.over) return;
  state.active='opponent';
  state.turn remains round number
  addLog('turn','兄のターン');
  resetTurnFlags(ai);
  drawCards(ai,1);
  render(); await sleep(350);
  await aiFlipSummons();
  await aiSetTrap();
  await aiPlaySpells();
  await aiSummon();
  await aiBattle();
  if (state.over) return;
  clearBoosts(ai);
  state.turn++;
  addLog('turn', `あなたのターン (TURN ${state.turn})`);
  state.active='player';
  resetTurnFlags(player);
  drawCards(player,1);
  state.busy=false;
  render();
}
```
Note busy stays true until end. Game start: state.busy false.

Timer loop:
```js
setInterval(() => { if(state.running) { state.elapsed=performance.now()-state.timerStart; $('#timer').textContent=fmt(state.elapsed);} }, 100);
```
Start once at init.

fmt: m:ss.t (tenths) e.g., 1:03.4.

Best: load from localStorage; display "BEST 0:58.2 / 4T"; after win, if better save.

Rank and best:
```js
function recordWin() {
  const time = state.elapsed; const turns = state.turn;
  const best = state.best;
  if (!best || time < best.time) { state.best={time,turns}; save; newRecord=true;}
  return newRecord;
}
```

Board build:
```js
const ZONE_LAYOUT = [ ... ];
function buildBoard() {
  const board = $('#board');
  board.innerHTML='';
  ZONE_LAYOUT.forEach(z => {
    const b=document.createElement('button');
    b.className = `zone ${z.area} ${z.owner||'shared'}`;
    b.style.gridRow=z.row; b.style.gridColumn=z.col;
    b.dataset.area=z.area; b.dataset.owner=z.owner||''; b.dataset.index=z.index ?? '';
    b.innerHTML='<span class="zone-label">...</span>';
    b.addEventListener('click',()=>onZoneClick(z));
    board.appendChild(b);
  });
}
```
Store `z` in closure for click.

