const aAtk=effAtk(attacker);
if (target.position==='defense') {
  const dDef=effDef(target);
  if (aAtk > dDef) { destroy(target); log(`…を破壊`); }
  else if (aAtk < dDef) { damage(attacker.owner, dDef-aAtk); }
