AI summon logic in detail:

```js
async function aiSummon() {
  const ai=..., pl=...;
  // EXTRA
  const own = allMonsters(ai);
  if (ai.extra.length && own.length>=2 && state.emz.some(x=>!x)) {
    const extraId = best extra (titan > linkdragon);
    const bestAtk = Math.max(...own.map(effAtk));
    if (CARD_DB[extraId].atk >= bestAtk + 200) {
      const tributes = own.sort(asc effAtk).slice(0,2);
      await specialSummon(ai, extraId, tributeInsts, emptyEmzIndex);
      return;
    }
  }
  // TRIBUTE
  const handMonsters = ai.hand.map((id,i)=>({id,i,card:CARD_DB[id]})).filter(x=>x.card.type==='monster');
  if (!handMonsters.length) return;
  const high = handMonsters.filter(x=>x.card.level>=5);
  if (high.length && own.length>=1) {
    const pick = high.sort(desc atk)[0];
    const tribute = own.sort(asc atk)[0];
    await aiNormalSummon(pick, 'attack', emptyMonsterIndex, [tribute]);
    return;
  }
  // SET decision
  const playerStrong = maxAtk(player);
  const best = handMonsters.sort(desc atk)[0];
  const guard = handMonsters.filter(x => x.card.def >= playerStrong).sort(desc def)[0];
  if ((playerStrong > best.card.atk && guard) || (ai.lp <= 2500 && guard)) {
    await aiNormalSummon(guard or best, 'set', emptyIndex, []);
  } else {
    await aiNormalSummon(best, 'attack', emptyIndex, []);
  }
}
