```js
function aiBestAttack(attacker) {
  const enemies = allMonsters(player);
  if (!enemies.length) return {target:null, score: effAtk(attacker)};
  let best=null;
  for (const t of enemies) {
    const a=effAtk(attacker);
    const def = (t.position==='defense'||t.faceDown) ? effDef(t) : effAtk(t);
    let score = 0;
    if (a > def) score = (t.position==='defense'||t.faceDown) ? 100 + effDef(t) : (a-def) + 500;
    else if (a < def) score = -999; // avoid
    else score = -100; // tie
    // lethal bonus
    if (score>0 && (t.position==='attack') && player.lp <= a-def) score += 10000;
    if (best===null || score>best.score) best={target:t, score, damage:...};
  }
  return best;
}
