async function summonMonster(sideKey, opts) {
  const gen=state.gameId;
  const side=state.players[sideKey];
  const from=copied name; 
  // tributes
  const tributes=(opts.tributes||[]).filter(t=>t && t.zone);
  for (const t of tributes) {
    addLog(sideKey, `${CARD_DB[t.id].name}を生贄に捧げた`, 'sys');
    removeInst(t, true, true); // no log destruction
  }
  // source
  if (opts.isExtra) {
    const exIdx = side.extra.indexOf(opts.cardId);
    if (exIdx>=0) side.extra.splice(exIdx,1);
  } else {
    if (opts.handIndex==null) opts.handIndex=side.hand.indexOf(opts.cardId);
    if (opts.handIndex>=0) side.hand.splice(opts.handIndex,1);
  }
  const inst=createInst(opts.cardId, sideKey);
  inst.position = opts.position==='set'?'defense':(opts.position||'attack');
  inst.faceDown = opts.position==='set';
  inst.changed = true;
  setInst(opts.zone, inst);
  if (!opts.isExtra) side.hasSummoned=true;
  const c=CARD_DB[opts.cardId];
  const posText = opts.position==='set'?'裏側守備表示でセット':opts.isExtra?'EXゾーンに特殊召喚':'攻撃表示で召喚';
  addLog(sideKey, `${c.name}を${posText}`, sideKey==='player'?'player':'opponent');
  sfx(opts.isExtra?'extra':'summon');
  banner(`${c.name} ${opts.position==='set'?'SET':opts.isExtra?'SUMMON':'SUMMON'}`, opts.isExtra?'summon':'summon');
  render();
  flashZone(inst,'zone-flash');
  await sleep(360);
  if (gen!==state.gameId) return null;
  // on summon
  if (c.onSummon?.burn) {
    damage(other(sideKey), c.onSummon.burn, c.name);
    if (!activeGame(gen)) return null;
  }
  if (c.onSummon?.destroyStrongest) {
    const target=strongestMonster(other(sideKey));
    if (target) { destroyInst(target); addLog(...); }
  }
  render();
  await checkPitfall(sideKey, inst);
  return inst;
}
