631:     `${CARD_DB[attacker.id].name}で${target ? `「${CARD_DB[target.id].name}」を攻撃` : 'ダイレクトアタック'}！`,
632:     atkKey === 'player' ? 'player' : 'opponent');
633:   sfx('attack');
634:   render();
635:   await sleep(260);
636:   if (gen !== state.gameId) return;
637: 
638:   const trapResult = await attackTrap(defKey, attacker, target);
639:   if (gen !== state.gameId) return;
640:   if (trapResult && trapResult.negated) {
