671:       } else {
672:         addLog('sys', '攻撃は弾かれた。', 'sys');
673:       }
674:     } else {
675:       const d = effAtk(target);
676:       addLog('sys', `攻撃力${a} VS 攻撃力${d}`, 'sys');
677:       if (a > d) {
678:         destroyInst(target);
679:         damage(defKey, a - d, '戦闘ダメージ');
680:       } else if (a < d) {
681:         destroyInst(attacker);
682:         damage(atkKey, d - a, '戦闘ダメージ');
683:       } else {
684:         destroyInst(attacker);
685:         destroyInst(target);
686:         addLog('damage', '相打ち！ 両者のモンスターが破壊された。', 'damage');
687:       }
688:     }
689:     impactAt(attacker, target);
690:   }
691: 
692:   if (morale && target && target.zone) target.boost = Math.max(0, target.boost - 1000);
693:   render();
694:   await sleep(320);
695:   if (gen !== state.gameId) return;
696:   finishAttack();
