470: function isTargetable(z) {
471:   const mode = state.mode;
472:   const pending = state.pending;
473:   const inst = getInst(z);
474:   if (mode === 'selectTribute') {
475:     return !!(inst && inst.owner === 'player' && isMonster(inst) && pending && !pending.selected.includes(inst.uid));
