477:   if (mode === 'placeMonster') {
478:     if (z.area !== 'monsters' || z.owner !== 'player') return false;
479:     if (!inst) return true;
480:     return !!(pending && pending.selected.includes(inst.uid));
481:   }
482:   if (mode === 'placeExtra') {
483:     return z.area === 'emz' && !inst;
484:   }
485:   if (mode === 'placeSpell') {
486:     return z.area === 'spells' && z.owner === 'player' && !inst;
487:   }
488:   if (mode === 'attackTarget' || mode === 'spellTarget') {
489:     return !!(inst && inst.owner === 'opponent' && isMonster(inst));
490:   }
491:   return false;
