584: /* ---------------- summon flow ---------------- */
585: function beginSummon(source, cardId, position, isExtra, sourceIndex) {
586:   if (state.busy || state.over || state.active !== 'player' || state.mode !== 'idle') return;
587:   const p = state.players.player;
588:   const c = CARD_DB[cardId];
589:   if (!isExtra && p.hasSummoned) { warnFlash('このターンはもう召喚している'); return; }
590: 
591:   const need = isExtra ? 2 : (c.level >= 5 ? 1 : 0);
592:   const own = allMonsters('player');
593:   if (own.length < need) { warnFlash(`生贄が足りない（${need}体必要）`); return; }
594:   if (isExtra && !state.emz.some((x) => !x)) { warnFlash('EXゾーンが空いていない'); return; }
595:   if (!isExtra && !canPlaceNormal(need)) { warnFlash('モンスターゾーンが空いていない'); return; }
596: 
597:   state.pending = { kind: 'summon', source, cardId, position, isExtra, sourceIndex, need, selected: [] };
598:   state.selection = null;
599:   state.mode = need > 0 ? 'selectTribute' : (isExtra ? 'placeExtra' : 'placeMonster');
600:   sfx('click');
601:   render();
602: }
