604: function toggleTribute(inst) {
605:   const p = state.pending;
606:   if (!p) return;
607:   const idx = p.selected.indexOf(inst.uid);
608:   if (idx >= 0) {
609:     p.selected.splice(idx, 1);
610:   } else {
611:     if (p.selected.length >= p.need) return;
612:     p.selected.push(inst.uid);
613:   }
614:   if (p.selected.length === p.need) {
615:     state.mode = p.isExtra ? 'placeExtra' : 'placeMonster';
616:   }
617:   sfx('click');
618:   render();
619: }
