280:         await performAttack(attacker, best.target);
281:       } else {
282:         addLog('opponent', '兄は攻撃を見送った。', 'opponent');
283:       }
284:     }
285: 
286:     if (!activeGame(gen)) return;
287:     if (!await pause(310, gen)) return;
